                }
              }
            }
          }
        }
      }
    },
    "out_of_scope_indicators": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "indicator",
          "finding",
          "source"
        ],
        "properties": {
          "indicator": {
            "type": "string",
            "enum": [
              "injury",
              "liability_dispute",
              "suspected_fraud",
              "recovery_or_third_party_claim",
              "other"
            ]
          },
          "finding": {
            "type": "string"
          },
          "source": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "document",
              "location"
            ],
            "properties": {
              "document": {
                "type": "string",
                "description": "File name, 'email' or 'policy record'."
              },
              "location": {
                "type": "string",
                "description": "Page, section, line or image region where the value or finding is."
              }
            }
          }
        }
      }
    },
    "proposed_hold": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "proposed",
        "reasons"
      ],
      "properties": {
        "proposed": {
          "type": "boolean"
        },
        "reasons": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "summary": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "overall",
        "statement"
      ],
      "properties": {
        "overall": {
          "type": "string",
          "enum": [
            "complete_and_consistent",
            "gaps_found",
            "conflicts_found",
            "gaps_and_conflicts_found",
            "processing_incomplete"
          ]
        },
        "statement": {
          "type": "string"
        }
      }
    }
